fn find_minimum_total_distance(x1: i8, x2: i8, x3: i8) -> i8 {
    // For three points on the real line, the point minimizing the sum of absolute distances
    // is the median of the three coordinates.
    let mut pts = [x1, x2, x3];
    pts.sort();
    let median = pts[1];

    // Sum of distances to the median
    (x1 - median).abs() + (x2 - median).abs() + (x3 - median).abs()
}

fn main() {
    // Example usage:
    assert_eq!(find_minimum_total_distance(1, 5, 3), 4);
    assert_eq!(find_minimum_total_distance(10, 1, 6), 9);
    println!("All tests passed!");
}